#include "Rover.h"

bool leftIsOpen() {
  turnLeft();
  bool open = distanceAhead() > 0;
  turnRight();
  return open;
}

bool rightIsOpen() {
  turnRight();
  bool open = distanceAhead() > 0;
  turnLeft();
  return open;
}

void setup() {
  forward(4);
  if (leftIsOpen()) {
    turnLeft();
  } else if (rightIsOpen()) {
    turnRight();
  }
  forward(2);
}

void loop() {
}
